package com.medtrack.auth.security; import com.medtrack.user.entity.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.SecretKey; import org.springframework.stereotype.Service;
@Service public class JwtService {private final JwtProperties props;private final SecretKey key;public JwtService(JwtProperties p){props=p;if(p.secret().getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("JWT secret must be at least 32 bytes");key=Keys.hmacShaKeyFor(p.secret().getBytes(StandardCharsets.UTF_8));}public String issue(User u){Instant now=Instant.now();List<String> permissions=u.getRole().getPermissions().stream().map(p->p.getName()).sorted().toList();return Jwts.builder().subject(u.getId().toString()).claim("email",u.getEmail()).claim("role",u.getRole().getName()).claim("warehouse_id",u.getAssignedWarehouse()==null?null:u.getAssignedWarehouse().getId().toString()).claim("permissions",permissions).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(props.accessTokenMinutes()*60))).signWith(key).compact();}public Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();}public long expiry(){return props.accessTokenMinutes()*60;}}
